<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import axios from'axios';import type{ApiEnvelope,AuthResult,Merchant,User}from'@local/types';
interface Dashboard{users:number;merchants:number;activeMerchants:number;pendingMerchants:number;conversations:number;merchantViews:number;consultConversionRate:number}interface ReviewMerchant extends Merchant{email?:string;createdAt?:string}
const api=axios.create({baseURL:import.meta.env.VITE_API_URL??'/api/v1'});const demoMode=import.meta.env.DEV;const token=ref(localStorage.getItem('adminToken'));api.interceptors.request.use(c=>{if(token.value)c.headers.Authorization=`Bearer ${token.value}`;return c});const email=ref(demoMode?'admin@machiservice.jp':'');const password=ref(demoMode?'Demo1234!':'');const page=ref('dashboard');const error=ref('');const stats=ref<Dashboard>({users:0,merchants:0,activeMerchants:0,pendingMerchants:0,conversations:0,merchantViews:0,consultConversionRate:0});const merchants=ref<ReviewMerchant[]>([]);const users=ref<User[]>([]);const selected=ref<ReviewMerchant|null>(null);const toast=ref('');const menus=[['dashboard','▦','ダッシュボード'],['users','♙','ユーザー'],['merchants','⌂','店舗'],['review','✓','店舗審査'],['categories','◇','カテゴリー'],['services','◫','サービス'],['products','□','商品'],['media','▧','メディア'],['conversations','✉','問い合わせ'],['banners','▤','バナー'],['reports','!','通報'],['analytics','↗','アクセス分析'],['settings','⚙','設定']];const title=computed(()=>menus.find(m=>m[0]===page.value)?.[2]);
async function login():Promise<void>{try{const r=await api.post<ApiEnvelope<AuthResult>>('/auth/login',{identifier:email.value,password:password.value});token.value=r.data.data.accessToken;localStorage.setItem('adminToken',r.data.data.accessToken);await load();}catch{error.value='ログインに失敗しました。'}}
async function load():Promise<void>{try{const[d,m,u]=await Promise.all([api.get<ApiEnvelope<Dashboard>>('/admin/dashboard'),api.get<ApiEnvelope<ReviewMerchant[]>>('/admin/merchants'),api.get<ApiEnvelope<User[]>>('/admin/users')]);stats.value=d.data.data;merchants.value=m.data.data;users.value=u.data.data;}catch{if(demoMode){merchants.value=[{id:'demo',nameJa:'大阪サンプル民泊清掃',status:'PENDING',rating:0,reviewCount:0,favoriteCount:0,email:'merchant@example.jp',createdAt:'2026/08/27',shortDescriptionJa:'大阪市内の民泊・ホテル清掃',address:{fullAddress:'大阪府大阪市西区南堀江1丁目2-3',municipalityName:'大阪市西区'}},{id:'active',nameJa:'なんばクリーンサポート',status:'ACTIVE',rating:4.7,reviewCount:85,favoriteCount:128,address:{fullAddress:'大阪府大阪市浪速区',municipalityName:'大阪市浪速区'}}];users.value=[{id:'1',nickname:'山田 花子',email:'customer@machiservice.jp',role:'CUSTOMER'},{id:'2',nickname:'大阪清掃 太郎',email:'merchant@machiservice.jp',role:'MERCHANT_ADMIN'}];}else{merchants.value=[];users.value=[];error.value='データを取得できませんでした。';}}}
async function review(action:'approve'|'reject'):Promise<void>{if(!selected.value)return;try{await api.post(`/admin/merchants/${selected.value.id}/${action}`,action==='reject'?{reason:'提出書類をご確認ください'}:{});}catch{if(!demoMode){error.value='審査結果を保存できませんでした。';return;}}selected.value.status=action==='approve'?'ACTIVE':'REJECTED';toast.value=action==='approve'?'店舗を承認しました':'店舗を否認しました';setTimeout(()=>toast.value='',2500);}
function logout():void{token.value=null;localStorage.removeItem('adminToken')}onMounted(()=>{if(token.value)void load()});
</script>
<template><div v-if="!token" class="login"><form @submit.prevent="login"><div class="logo"><i>ま</i><b>まちサービス<small>運営管理</small></b></div><span>PLATFORM ADMIN</span><h1>運営管理にログイン</h1><p>サービス全体の健全な運営を支えます。</p><label>メールアドレス<input v-model="email"></label><label>パスワード<input v-model="password" type="password"></label><em v-if="error">{{ error }}</em><button>ログイン</button></form><div><b>LOCAL TRUST,<br>BETTER TOWNS.</b></div></div><div v-else class="shell"><aside><div class="logo"><i>ま</i><b>まちサービス<small>運営管理</small></b></div><nav><button v-for="menu in menus" :key="menu[0]" :class="{active:page===menu[0]}" @click="page=menu[0]!"><i>{{ menu[1] }}</i>{{ menu[2] }}<span v-if="menu[0]==='review'">{{ stats.pendingMerchants }}</span></button></nav><button class="logout" @click="logout">ログアウト</button></aside><main><header><div><span>PLATFORM OVERVIEW</span><h1>{{ title }}</h1></div><div class="admin"><i>運</i><b>運営管理者<small>SUPER ADMIN</small></b></div></header><section v-if="page==='dashboard'"><div class="notice"><b>審査待ちの店舗が {{ stats.pendingMerchants }}件あります</b><p>提出内容を確認して、公開可否を判断してください。</p><button @click="page='review'">審査を確認 →</button></div><div class="cards"><article><span>登録ユーザー</span><strong>{{ stats.users.toLocaleString() }}</strong><small>↗ 6.4% 前月比</small></article><article><span>掲載店舗</span><strong>{{ stats.merchants }}</strong><small>公開中 {{ stats.activeMerchants }}</small></article><article><span>月間店舗閲覧</span><strong>{{ stats.merchantViews.toLocaleString() }}</strong><small>↗ 12.8% 前月比</small></article><article><span>問い合わせ数</span><strong>{{ stats.conversations }}</strong><small>転換率 {{ stats.consultConversionRate }}%</small></article></div><div class="columns"><article class="panel"><div class="panel-head"><h3>店舗登録状況</h3><span>過去7日間</span></div><div class="chart"><i v-for="height in [32,48,42,64,56,82,70]" :key="height" :style="{height:`${height}%`}"></i></div><div class="days"><span v-for="day in ['木','金','土','日','月','火','水']" :key="day">{{ day }}</span></div></article><article class="panel"><div class="panel-head"><h3>最近の審査申請</h3><button @click="page='review'">すべて見る</button></div><div v-for="merchant in merchants.filter(m=>m.status==='PENDING').slice(0,3)" :key="merchant.id" class="row"><i>店</i><div><b>{{ merchant.nameJa }}</b><small>{{ merchant.address?.municipalityName }} · {{ merchant.shortDescriptionJa }}</small></div><button @click="selected=merchant">確認</button></div><div v-if="!merchants.some(m=>m.status==='PENDING')" class="empty">審査待ちはありません</div></article></div></section><section v-else-if="page==='review'||page==='merchants'" class="panel table-panel"><div class="panel-head"><div><h3>{{ title }}</h3><p>店舗の登録内容と公開状態を管理します。</p></div><input placeholder="店舗名で検索"></div><table><thead><tr><th>店舗</th><th>所在地</th><th>申請日</th><th>状態</th><th></th></tr></thead><tbody><tr v-for="merchant in page==='review'?merchants.filter(m=>m.status==='PENDING'):merchants" :key="merchant.id"><td><b>{{ merchant.nameJa }}</b><small>{{ merchant.shortDescriptionJa }}</small></td><td>{{ merchant.address?.municipalityName }}</td><td>{{ merchant.createdAt??'2026/08/27' }}</td><td><span :class="merchant.status.toLowerCase()">{{ merchant.status==='PENDING'?'審査中':merchant.status==='ACTIVE'?'公開中':'否認' }}</span></td><td><button @click="selected=merchant">詳細 →</button></td></tr></tbody></table></section><section v-else-if="page==='users'" class="panel table-panel"><div class="panel-head"><h3>ユーザー一覧</h3><input placeholder="名前・メールで検索"></div><table><thead><tr><th>ユーザー</th><th>メール</th><th>権限</th><th>状態</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td><b>{{ user.nickname }}</b></td><td>{{ user.email }}</td><td>{{ user.role }}</td><td><span class="active">有効</span></td></tr></tbody></table></section><section v-else class="panel placeholder"><b>{{ menus.find(m=>m[0]===page)?.[1] }}</b><h2>{{ title }}</h2><p>この管理機能はAPIエンドポイントを備えたMVP画面です。</p></section></main><div v-if="selected" class="drawer"><button class="close" @click="selected=null">×</button><span>MERCHANT REVIEW</span><h2>{{ selected.nameJa }}</h2><div class="status">審査中</div><dl><dt>所在地</dt><dd>{{ selected.address?.fullAddress }}</dd><dt>業種</dt><dd>{{ selected.shortDescriptionJa }}</dd><dt>連絡先</dt><dd>{{ selected.email??'merchant@example.jp' }}</dd><dt>本人・法人確認</dt><dd>提出済み ✓</dd></dl><div class="document">▧<b>本人確認書類.pdf</b><small>確認する ↗</small></div><textarea placeholder="否認理由（否認する場合）"></textarea><div class="actions"><button @click="review('reject')">否認する</button><button @click="review('approve')">承認して公開</button></div></div><div v-if="selected" class="overlay" @click="selected=null"></div><div v-if="toast" class="toast">✓ {{ toast }}</div></div></template>
